/* Pengajuan is manual tracking of a Bank process, independent of sales stages. */
const APPLICATION_FIELDS={survey:{label:'Survey',values:['Belum dimulai','Terjadwal','Dalam proses','Selesai','Tidak berlaku']},analysis:{label:'Analisa',values:['Belum dimulai','Dalam proses','Selesai','Perlu perbaikan','Tidak berlaku']},approval:{label:'Approval',values:['Belum diputuskan','Dalam review','Disetujui','Ditolak','Tidak berlaku']},disbursement:{label:'Pencairan / realisasi',values:['Belum dicairkan','Dalam proses','Dicairkan','Tidak berlaku']}};
let applicationFilters={category:'all',owner:'',product:'',month:''},applicationHistoryPage=1,applicationFocus='';
function applicationVisible(){return db.applications.filter(a=>mine(a)&&!!opp(a.opp)&&mine(opp(a.opp)))}
function trackedApplication(id){return applicationVisible().find(a=>a.id===id)}
function applicationState(a){if(a.disbursement==='Dicairkan')return 'realized';if(a.approval==='Ditolak')return 'rejected';if(a.analysis==='Perlu perbaikan')return 'revision';if(a.approval==='Disetujui')return 'approved';if(a.approval==='Dalam review'||['Terjadwal','Dalam proses','Selesai'].includes(a.survey)||['Dalam proses','Selesai'].includes(a.analysis)||a.disbursement==='Dalam proses')return 'process';return 'new'}
const APPLICATION_CATEGORIES={all:'Semua',new:'Belum diproses',process:'Dalam proses',revision:'Perlu perbaikan',approved:'Disetujui',rejected:'Ditolak',realized:'Sudah dicairkan'};
function applicationTag(value){const tone=/Ditolak|Perlu perbaikan/.test(value)?'danger':/Dicairkan|Disetujui|Selesai/.test(value)?'success':/Dalam|Terjadwal/.test(value)?'pending':'neutral';return '<span class="application-status '+tone+'">'+E(value||'Belum tercatat')+'</span>'}
function applicationFilter(key,value){applicationFilters[key]=value;listPage=1;renderContent()}
function applicationMatches(a,category=true){const o=opp(a.opp),query=appSearch.trim().toLowerCase();return (typeof dateRecordMatches!=='function'||dateRecordMatches('Pengajuan',a))&&(!query||[a.number,pname(a.profile),o?.name,a.product,a.source,a.id].join(' ').toLowerCase().includes(query))&&(!applicationFilters.owner||(a.owner||o?.owner)===applicationFilters.owner)&&(!applicationFilters.product||a.product===applicationFilters.product)&&(!applicationFilters.month||(a.updated||a.created||'').startsWith(applicationFilters.month))&&(!category||applicationFilters.category==='all'||applicationState(a)===applicationFilters.category)}
function applicationSelectFilter(label,key,values){return '<label>'+label+'<select onchange="applicationFilter(\''+key+'\',this.value)"><option value="">Semua</option>'+values.map(v=>'<option '+(applicationFilters[key]===v?'selected':'')+' value="'+E(v)+'">'+E(v)+'</option>').join('')+'</select></label>'}
applicationListConnected=function(){const visible=applicationVisible(),base=visible.filter(a=>applicationMatches(a,false)),rows=visible.filter(a=>applicationMatches(a)),items=pageItems(rows),unique=key=>[...new Set(visible.map(a=>a[key]|| (key==='owner'?opp(a.opp)?.owner:'')).filter(Boolean))];
return '<div class="applications-v2">'+titleBlock('Pengajuan','Pantau status proses Bank yang terhubung ke Opportunity.',btn('Tautkan pengajuan','applicationForm()',true))+'<div class="application-notice"><strong>Tracking proses Bank</strong><span>AO mencatat pembaruan dari proses Bank. Tahap pemasaran Opportunity tetap dikelola terpisah; halaman ini tidak menjalankan persetujuan kredit atau pencairan.</span></div><div class="rangechips application-chips">'+Object.entries(APPLICATION_CATEGORIES).map(([key,label])=>'<button class="'+(applicationFilters.category===key?'active':'')+'" aria-pressed="'+(applicationFilters.category===key)+'" onclick="applicationFilter(\'category\',\''+key+'\')">'+label+' <b>'+base.filter(a=>key==='all'||applicationState(a)===key).length+'</b></button>').join('')+'</div><div class="application-filters"><label class="application-search">Cari pengajuan<input aria-label="Cari pengajuan" placeholder="Nomor pengajuan, customer, produk atau Opportunity" value="'+E(appSearch)+'" oninput="applicationSearch(this.value)"></label>'+applicationSelectFilter('Penanggung jawab','owner',unique('owner'))+applicationSelectFilter('Produk','product',unique('product'))+'<label>Bulan pembaruan<input aria-label="Bulan pembaruan pengajuan" type="month" value="'+E(applicationFilters.month)+'" onchange="applicationFilter(\'month\',this.value)"></label>'+btn('Reset filter',"dateFilterClear('Pengajuan');applicationFilters={category:'all',owner:'',product:'',month:''};appSearch='';listPage=1;renderContent()")+'</div><div class="listhead"><strong>'+rows.length+' pengajuan sesuai filter</strong><small>Klik baris untuk melihat detail dan histori.</small></div>'+(rows.length?(mobile?'<div class="records">'+items.map(applicationCard).join('')+'</div>':'<div class="scrolltable"><table class="datatable application-table"><thead><tr><th>Pengajuan & customer</th><th>Opportunity / AO</th><th>Survey</th><th>Analisa</th><th>Approval</th><th>Pencairan</th><th>Pembaruan</th></tr></thead><tbody>'+items.map(a=>{const o=opp(a.opp);return '<tr tabindex="0" role="link" aria-label="Buka pengajuan '+E(a.number)+'" onclick="if(!event.target.closest(\'button,a\'))openApplication('+E(JSON.stringify(a.id))+')" onkeydown="if(event.target===this&&(event.key===\'Enter\'||event.key===\' \')){event.preventDefault();openApplication('+E(JSON.stringify(a.id))+')}"><td><button class="application-number" onclick="openApplication('+E(JSON.stringify(a.id))+')">'+E(a.number)+'</button><strong>'+E(pname(a.profile))+'</strong><small>'+E(a.product)+'</small></td><td><strong>'+E(o.name)+'</strong><small>'+E(a.owner||o.owner)+' · '+E(o.stage)+'</small></td>'+Object.keys(APPLICATION_FIELDS).map(k=>'<td>'+applicationTag(a[k])+'</td>').join('')+'<td>'+E(fmt(a.updated||a.created))+'<small>'+E(a.updatedBy||a.history?.at(-1)?.actor||'Belum tercatat')+'</small></td></tr>'}).join('')+'</tbody></table></div>'):empty('Tidak ada pengajuan sesuai filter. Tautkan nomor pengajuan dari Opportunity atau reset filter.'))+pager(rows.length)+'<p class="hint">Chip meringkas kondisi terkini: pencairan → penolakan → perbaikan → persetujuan → proses → belum diproses. Lihat empat status terpisah untuk detail.</p></div>';
};
applicationCard=function(a){return '<article class="record application-card" tabindex="0" role="link" aria-label="Buka pengajuan '+E(a.number)+'" onclick="if(!event.target.closest(\'button,a\'))openApplication('+E(JSON.stringify(a.id))+')" onkeydown="if(event.target===this&&event.key===\'Enter\')openApplication('+E(JSON.stringify(a.id))+')"><div class="recordtop">'+applicationTag(APPLICATION_CATEGORIES[applicationState(a)])+'<small>Input manual</small></div><h3>'+E(a.number)+'</h3><p>'+E(pname(a.profile))+' · '+E(a.product)+'</p><small>'+E(opp(a.opp)?.name)+'</small><div class="application-card-statuses">'+Object.entries(APPLICATION_FIELDS).map(([k,f])=>'<div><small>'+f.label+'</small>'+applicationTag(a[k])+'</div>').join('')+'</div><small>Diperbarui '+E(fmt(a.updated||a.created))+'</small><div class="actions">'+btn('Lihat detail','openApplication('+E(JSON.stringify(a.id))+')',true)+btn('Update status','applicationForm('+E(JSON.stringify(a.opp))+','+E(JSON.stringify(a.id))+')')+'</div></article>'};
function openApplication(id){if(!trackedApplication(id))return toast('Pengajuan tidak tersedia dalam akses Anda.');applicationFocus=id;applicationHistoryPage=1;go('Pengajuan detail',id)}
function applicationLink(label,route,id){return btn(E(label),'go('+E(JSON.stringify(route))+','+E(JSON.stringify(id))+')')}
function applicationHistoryChanges(h){if(!h.before)return '<p class="hint">'+(h.after?'Pencatatan awal pengajuan.':'Catatan histori lama; rincian status sebelum dan sesudah belum tersedia.')+'</p>';const after=h.after||{},keys=['number','product',...Object.keys(APPLICATION_FIELDS),'source'],labels={number:'Nomor pengajuan',product:'Produk',source:'Sumber / referensi',...Object.fromEntries(Object.entries(APPLICATION_FIELDS).map(([k,v])=>[k,v.label]))};const changed=keys.filter(k=>Object.hasOwn(after,k)&&h.before[k]!==after[k]);return changed.length?'<div class="application-changes">'+changed.map(k=>'<div><b>'+labels[k]+'</b><span>'+E(h.before[k]||'Belum tercatat')+'</span><span aria-label="menjadi">→</span><strong>'+E(after[k]||'Belum tercatat')+'</strong></div>').join('')+'</div>':'<p class="hint">Catatan pembaruan tanpa perubahan status.</p>'}
function applicationDetailScreen(id){const a=trackedApplication(id);if(!a)return titleBlock('Pengajuan tidak tersedia','Record tidak ditemukan atau di luar akses akun.')+btn('Kembali ke pengajuan',"go('Pengajuan')");const o=opp(a.opp),p=profile(a.profile),history=[...(a.history||[])].reverse(),pages=Math.max(1,Math.ceil(history.length/8));applicationHistoryPage=Math.max(1,Math.min(pages,applicationHistoryPage));const lead=db.leads.find(l=>l.id===o.lead||l.profile===a.profile);
return '<div class="applications-v2">'+btn('← Kembali ke daftar pengajuan',"go('Pengajuan')")+'<section class="application-hero"><div><small>REFERENSI PENGAJUAN BANK</small><h1>'+E(a.number)+'</h1><p>'+E(pname(a.profile))+' · '+E(a.product)+'</p>'+applicationTag(APPLICATION_CATEGORIES[applicationState(a)])+'</div><div class="actions">'+btn('Update status','applicationForm('+E(JSON.stringify(a.opp))+','+E(JSON.stringify(a.id))+')',true)+applicationLink('Buka Opportunity','Opportunity detail',a.opp)+'</div></section><div class="application-notice"><strong>Pembaruan manual pada POC</strong><span>Nomor dan status mengikuti informasi proses Bank. Tidak ada perubahan otomatis pada tahap Opportunity atau keputusan kredit.</span></div><section class="application-panel"><h2>Status proses Bank</h2><p class="hint">Empat status dipantau terpisah, bukan indikator persentase penyelesaian.</p><div class="application-states">'+Object.entries(APPLICATION_FIELDS).map(([k,f])=>'<div><span>'+f.label+'</span>'+applicationTag(a[k])+'</div>').join('')+'</div></section><div class="application-two-column"><section class="application-panel"><h2>Pengajuan & hubungan data</h2>'+detailFacts([['Nomor pengajuan',a.number],['Produk',a.product],['Lead / customer',pname(a.profile)],['Opportunity',o.name],['Tahap pemasaran',o.stage],['AO penanggung jawab',a.owner||o.owner],['Tanggal dicatat',a.created?fmt(a.created):a.history?.[0]?.time?fmt(a.history[0].time):'Belum tercatat']])+'<div class="actions">'+(p?.relation==='Customer'?applicationLink('Buka Customer 360','Nasabah detail',a.profile):lead?applicationLink('Buka Lead','Lead detail',lead.id):'')+btn('Buat Task follow-up','newTask('+E(JSON.stringify(a.profile))+','+E(JSON.stringify(a.opp))+','+E(JSON.stringify(o.lead||''))+')')+'</div></section><section class="application-panel"><h2>Pembaruan terakhir</h2>'+detailFacts([['Waktu pembaruan',fmt(a.updated||a.created)],['Diperbarui oleh',a.updatedBy||a.history?.at(-1)?.actor||'Belum tercatat'],['Sumber / referensi',a.source||'Belum tercatat'],['Catatan',a.note||a.history?.at(-1)?.note||'Belum ada catatan']])+'<p class="hint">Catat sumber informasi agar setiap status dapat ditelusuri kembali.</p></section></div><section class="application-panel"><div class="listhead"><h2>Riwayat perubahan</h2><small>'+history.length+' pembaruan</small></div><div class="application-timeline">'+(history.slice((applicationHistoryPage-1)*8,applicationHistoryPage*8).map(h=>'<article><div class="application-history-head"><strong>'+E(fmt(h.time))+'</strong><span>'+E(h.actor||'Tidak tercatat')+'</span></div><p>'+E(h.note||'Tanpa catatan')+'</p>'+applicationHistoryChanges(h)+(h.after?.source?'<small>Sumber / referensi: '+E(h.after.source)+'</small>':'')+'</article>').join('')||empty('Belum ada riwayat yang tercatat.'))+'</div><div class="dash-pagination"><button '+(applicationHistoryPage===1?'disabled':'')+' onclick="applicationHistoryPage--;renderContent()">Sebelumnya</button><span>'+applicationHistoryPage+' / '+pages+'</span><button '+(applicationHistoryPage===pages?'disabled':'')+' onclick="applicationHistoryPage++;renderContent()">Berikutnya</button></div></section></div>'}
function applicationChoice(label,name,values,current){return '<label>'+label+'<select name="'+name+'" required>'+values.map(v=>'<option value="'+E(v)+'" '+(v===current?'selected':'')+'>'+E(v)+'</option>').join('')+'</select></label>'}
function applicationUpdateContext(){const f=document.querySelector('#form'),o=opp(f.elements.appOpportunity?.value);if(!o)return;const n=document.querySelector('#applicationContext');n.textContent=pname(o.profile)+' · '+o.owner+' · Tahap pemasaran: '+o.stage;if(f.elements.product)f.elements.product.value=o.product||''}
applicationForm=function(oid='',id=''){
 const a=id?trackedApplication(id):null;if(id&&!a)return toast('Pengajuan tidak tersedia.');const choices=visible(db.opps),o=opp(oid||a?.opp)||choices[0];if(!o||!mine(o))return toast('Buat atau pilih Opportunity terlebih dahulu.');
 const pick=id?'': '<label>Opportunity terkait<select name="appOpportunity" required onchange="applicationUpdateContext()">'+choices.map(x=>'<option value="'+E(x.id)+'" '+(x.id===o.id?'selected':'')+'>'+E(x.name)+' — '+E(pname(x.profile))+'</option>').join('')+'</select></label>';
 modal(id?'Perbarui pengajuan':'Tautkan pengajuan ke Opportunity','<p class="application-notice">Pencatatan manual informasi proses Bank. Tidak menjalankan keputusan approval atau pencairan.</p>'+pick+'<p id="applicationContext" class="hint">'+E(pname(o.profile)+' · '+o.owner+' · Tahap pemasaran: '+o.stage)+'</p><div class="application-form-grid">'+field('Nomor pengajuan / referensi Bank','number',a?.number||'','text',true)+field('Produk','product',a?.product||o.product||'','text',true)+Object.entries(APPLICATION_FIELDS).map(([k,f])=>applicationChoice(f.label,k,f.values,a?.[k]||f.values[0])).join('')+'</div>'+field('Sumber / referensi pembaruan','source',a?.source||'','text',true)+area('Catatan pembaruan / alasan perubahan','note','',true)+'<p class="hint">Semua perubahan dicatat bersama waktu dan petugas. Jika approval diperlukan, status Dicairkan memerlukan approval Disetujui. Pilih Tidak berlaku untuk proses yang tidak memerlukan approval.</p>',f=>{
 if(saving&&!journey)throw Error('Tunggu penyimpanan sebelumnya selesai.');const parent=opp(a?.opp||f.appOpportunity||o.id);if(!parent||!mine(parent))throw Error('Opportunity tidak tersedia.');
 const number=f.number.trim(),product=f.product.trim(),source=f.source.trim(),note=f.note.trim();if(!number||!product||!source||!note)throw Error('Lengkapi nomor, produk, sumber dan catatan.');
 if(db.applications.some(x=>x.id!==id&&String(x.number||'').trim().toLowerCase()===number.toLowerCase()))throw Error('Nomor pengajuan sudah ditautkan. Buka pengajuan existing.');
 for(const [k,def]of Object.entries(APPLICATION_FIELDS))if(!def.values.includes(f[k]))throw Error('Status '+def.label+' tidak valid.');
 if(f.disbursement==='Dicairkan'&&!['Disetujui','Tidak berlaku'].includes(f.approval))throw Error('Konfirmasi approval Disetujui, atau Tidak berlaku jika proses Bank tidak memerlukannya.');
 const stamp=now(),next={number,product,survey:f.survey,analysis:f.analysis,approval:f.approval,disbursement:f.disbursement,source,note};const before=a?Object.fromEntries(Object.keys(next).map(k=>[k,a[k]??''])):null;
 let target=a;if(!target){target={id:uid('AP'),profile:parent.profile,opp:parent.id,owner:parent.owner,ownerId:parent.ownerId||memberList.find(m=>m.name===parent.owner)?.id,created:stamp,history:[]};db.applications.push(target)}
 target.history=Array.isArray(target.history)?target.history:[];target.history.push({time:stamp,actor:actor(),note,before,after:{...next}});Object.assign(target,next,{updated:stamp,updatedBy:actor()});record(id?'Update status pengajuan':'Tautkan pengajuan',target.id,number+' / '+note);setTimeout(()=>openApplication(target.id),0);
 });
};
const applicationNavigationParent=navigationParent;
navigationParent=function(v){return v==='Pengajuan detail'?'Pengajuan':applicationNavigationParent(v)};
const applicationContentBefore=renderContent;
renderContent=function(){if(view==='Pengajuan detail'){document.querySelector('#app').innerHTML=applicationDetailScreen(focus||applicationFocus);return}return applicationContentBefore()};
